arguments.prompt:
You are working on a Blazor Web App at `/tmp/sv-c8506f61ecc5463eb1a90a2b86c6995c/ShipmentTracker`. The solution has two projects:
- `ShipmentTracker` (server) - has Data folder with ApplicationDbContext (IdentityDbContext), Program.cs, Components folder
- `ShipmentTracker.Client` (WASM client) - has Pages folder, _Imports.razor

The app uses Auto render mode (Server + WebAssembly), Individual auth with ASP.NET Core Identity, and SQLite.

I need you to implement shipment tracking features:

## 1. Create a Shipment model

Create `/tmp/sv-c8506f61ecc5463eb1a90a2b86c6995c/ShipmentTracker/ShipmentTracker/Data/Shipment.cs`:
```csharp
namespace ShipmentTracker.Data;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string RecipientEmail { get; set; } = string.Empty;
    public string? CustomerId { get; set; }
    public ApplicationUser? Customer { get; set; }
    public string? DispatcherId { get; set; }
    public ApplicationUser? Dispatcher { get; set; }
}
```

## 2. Create a shared DTO in the Client project

Create `/tmp/sv-c8506f61ecc5463eb1a90a2b86c6995c/ShipmentTracker/ShipmentTracker.Client/ShipmentDto.cs`:
```csharp
namespace ShipmentTracker.Client;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string RecipientEmail { get; set; } = string.Empty;
}
```

## 3. Update ApplicationDbContext

Edit `/tmp/sv-c8506f61ecc5463eb1a90a2b86c6995c/ShipmentTracker/ShipmentTracker/Data/ApplicationDbContext.cs` to:
```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(entity =>
        {
            entity.HasIndex(s => s.TrackingNumber).IsUnique();
            entity.HasOne(s => s.Customer)
                .WithMany()
                .HasForeignKey(s => s.CustomerId)
                .OnDelete(DeleteBehavior.SetNull);
            entity.HasOne(s => s.Dispatcher)
                .WithMany()
                .HasForeignKey(s => s.DispatcherId)
                .OnDelete(DeleteBehavior.SetNull);
        });
    }
}
```

## 4. Add API endpoints to Program.cs

In `/tmp/sv-c8506f61ecc5463eb1a90a2b86c6995c/ShipmentTracker/ShipmentTracker/Program.cs`, add these lines BEFORE `app.Run();`:

```csharp
// Shipment API endpoints
app.MapGet("/api/shipments", async (ApplicationDbContext db, HttpContext http) =>
{
    var user = http.User;
    if (!user.Identity?.IsAuthenticated ?? true)
        return Results.Unauthorized();

    var userId = user.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
    var shipments = await db.Shipments
        .OrderByDescending(s => s.CreatedAt)
        .Select(s => new ShipmentTracker.Client.ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = (ShipmentTracker.Client.ShipmentStatus)(int)s.Status,
            CreatedAt = s.CreatedAt,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            RecipientName = s.RecipientName,
            RecipientEmail = s.RecipientEmail
        })
        .ToListAsync();

    return Results.Ok(shipments);
}).RequireAuthorization();

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments
        .Where(s => s.TrackingNumber == trackingNumber)
        .Select(s => new ShipmentTracker.Client.ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = (ShipmentTracker.Client.ShipmentStatus)(int)s.Status,
            CreatedAt = s.CreatedAt,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            RecipientName = s.RecipientName,
            RecipientEmail = s.RecipientEmail
        })
        .FirstOrDefaultAsync();

    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

app.MapPost("/api/shipments", async (ShipmentTracker.Client.ShipmentDto dto, ApplicationDbContext db, HttpContext http) =>
{
    var userId = http.User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;

    var shipment = new ShipmentTracker.Data.Shipment
    {
        TrackingNumber = dto.TrackingNumber,
        Origin = dto.Origin,
        Destination = dto.Destination,
        Status = (ShipmentTracker.Data.ShipmentStatus)(int)dto.Status,
        CreatedAt = DateTime.UtcNow,
        EstimatedDelivery = dto.EstimatedDelivery,
        RecipientName = dto.RecipientName,
        RecipientEmail = dto.RecipientEmail,
        DispatcherId = userId
    };

    db.Shipments.Add(shipment);
    await db.SaveChangesAsync();

    dto.Id = shipment.Id;
    dto.CreatedAt = shipment.CreatedAt;
    return Results.Created($"/api/shipments/{shipment.Id}", dto);
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}", async (int id, ShipmentTracker.Client.ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();

    shipment.Status = (ShipmentTracker.Data.ShipmentStatus)(int)dto.Status;
    shipment.Destination = dto.Destination;
    shipment.EstimatedDelivery = dto.EstimatedDelivery;
    shipment.ActualDelivery = dto.ActualDelivery;

    await db.SaveChangesAsync();
    return Results.NoContent();
}).RequireAuthorization();
```

Also add `using Microsoft.EntityFrameworkCore;` at the top of Program.cs if not already there.

## 5. Create the Dispatcher Dashboard page (Client project)

Create `/tmp/sv-c8506f61ecc5463eb1a90a2b86c6995c/ShipmentTracker/ShipmentTracker.Client/Pages/Shipments.razor`:
```razor
@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using System.Net.Http.Json
@attribute [Authorize]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Shipments Dashboard</PageTitle>

<h1>Shipments Dashboard</h1>

<div class="mb-3 d-flex gap-2">
    <input type="text" class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    <select class="form-select w-auto" @bind="statusFilter">
        <option value="">All Statuses</option>
        @foreach (var status in Enum.GetValues<ShipmentStatus>())
        {
            <option value="@status">@status</option>
        }
    </select>
    <button class="btn btn-primary text-nowrap" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input type="text" class="form-control" placeholder="Tracking #" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-2">
                    <input type="text" class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-2">
                    <input type="text" class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-2">
                    <input type="text" class="form-control" placeholder="Recipient" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-2">
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-md-1">
                    <button class="btn btn-success w-100" @onclick="CreateShipment">Save</button>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(createError))
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
