            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = (ShipmentTracker.Client.ShipmentStatus)(int)s.Status,
            CreatedAt = s.CreatedAt,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            RecipientName = s.RecipientName,
            RecipientEmail = s.RecipientEmail
        })
        .ToListAsync();

    return Results.Ok(shipments);
}).RequireAuthorization();

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments
        .Where(s => s.TrackingNumber == trackingNumber)
        .Select(s => new ShipmentTracker.Client.ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = (ShipmentTracker.Client.ShipmentStatus)(int)s.Status,
            CreatedAt = s.CreatedAt,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            RecipientName = s.RecipientName,
            RecipientEmail = s.RecipientEmail
        })
        .FirstOrDefaultAsync();

    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

app.MapPost("/api/shipments", async (ShipmentTracker.Client.ShipmentDto dto, ApplicationDbContext db, HttpContext http) =>
{
    var userId = http.User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;

    var shipment = new ShipmentTracker.Data.Shipment
    {
        TrackingNumber = dto.TrackingNumber,
        Origin = dto.Origin,
        Destination = dto.Destination,
        Status = (ShipmentTracker.Data.ShipmentStatus)(int)dto.Status,
        CreatedAt = DateTime.UtcNow,
        EstimatedDelivery = dto.EstimatedDelivery,
        RecipientName = dto.RecipientName,
        RecipientEmail = dto.RecipientEmail,
        DispatcherId = userId
    };

    db.Shipments.Add(shipment);
    await db.SaveChangesAsync();

    dto.Id = shipment.Id;
    dto.CreatedAt = shipment.CreatedAt;
    return Results.Created($"/api/shipments/{shipment.Id}", dto);
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}", async (int id, ShipmentTracker.Client.ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();

    shipment.Status = (ShipmentTracker.Data.ShipmentStatus)(int)dto.Status;
    shipment.Destination = dto.Destination;
    shipment.EstimatedDelivery = dto.EstimatedDelivery;
    shipment.ActualDelivery = dto.ActualDelivery;

    await db.SaveChangesAsync();
    return Results.NoContent();
}).RequireAuthorization();
